// One party's wallets from one BIP-39 seed generated by WDK core:
// - the party key at m/86'/1'/0'/0/0 (x-only): Passbook identity, Nostr key,
//   escrow leaf signer, and through its BIP-86 key-path address the party's BTC;
// - the RGB wallet (WDK RGB module), whose own BIP-86 accounts rgb-lib derives
//   at m/86'/1'/0'/1/* (vanilla) and m/86'/827167'/0' (colored), so the paths
//   never overlap with the party key.
// Seeds live in <wallets>/<role>/seed (git-ignored, mode 600), RGB data in
// <wallets>/<role>/rgb. One directory per party, never shared between processes.

import { schnorr } from '@noble/curves/secp256k1.js'
import { HDKey } from '@scure/bip32'
import { mnemonicToSeedSync } from '@scure/bip39'
import WDK from '@tetherto/wdk'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { bytesToHex, type KeyPair } from '../core/crypto.js'
import { keyPathOutput } from '../escrow/escrow.js'
import { RgbWallet, type RgbConfig, rgbConfigFromEnv } from '../rgb/wallet.js'
import { walletsDir } from './platform-key.js'

export type Role = 'borrower' | 'lender1' | 'lender2' | 'payer'
export const ROLES: Role[] = ['borrower', 'lender1', 'lender2', 'payer']
export type PersonaRole = 'fatima' | 'walter' | 'client1' | 'client2' | 'client3' | 'client4' | 'wash-payer' | 'wash-proxy'
export type WalletRole = Role | PersonaRole
export const PARTY_KEY_PATH = "m/86'/1'/0'/0/0"

export { walletsDir } from './platform-key.js'

export function newSeedPhrase(): string {
  return WDK.getRandomSeedPhrase(12)
}

export function partyKey(seedPhrase: string): KeyPair {
  const node = HDKey.fromMasterSeed(mnemonicToSeedSync(seedPhrase)).derive(PARTY_KEY_PATH)
  if (!node.privateKey) throw new Error('no private key at the party path')
  const secretKey = node.privateKey
  return { secretKey, pubkey: bytesToHex(schnorr.getPublicKey(secretKey)) }
}

/** Reads <dir>/<role>/seed, or creates it with a fresh WDK seed when `create` is set. */
export function loadSeed(role: WalletRole, opts: { dir?: string; create?: boolean } = {}): string {
  const dir = join(opts.dir ?? walletsDir(), role)
  const file = join(dir, 'seed')
  if (existsSync(file)) return readFileSync(file, 'utf8').trim()
  if (!opts.create) throw new Error(`no wallet for ${role} in ${dir}; run npm run seed`)
  mkdirSync(dir, { recursive: true, mode: 0o700 })
  const phrase = newSeedPhrase()
  writeFileSync(file, `${phrase}\n`, { mode: 0o600 })
  return phrase
}

export interface Party {
  role: WalletRole
  key: KeyPair
  /** BIP-86 key-path address of the party key: the borrower's collateral, a lender's split or liquidation proceeds */
  btcAddress: string
  btcScript: string
  rgb: RgbWallet
  close(): void
}

export async function openParty(role: WalletRole, opts: { dir?: string; create?: boolean; rgb?: RgbConfig } = {}): Promise<Party> {
  const dir = opts.dir ?? walletsDir()
  const seed = loadSeed(role, { dir, create: opts.create })
  const key = partyKey(seed)
  const out = keyPathOutput(key.pubkey)
  const rgb = await RgbWallet.open(seed, join(dir, role, 'rgb'), opts.rgb ?? rgbConfigFromEnv())
  return { role, key, btcAddress: out.address, btcScript: out.script, rgb, close: () => rgb.close() }
}

